class Solution
{
public:
    string rearrangeString(string s, int k)
    {
        if (k <= 1) return s;
        unordered_map<char, int> freq;
        for (char c : s) ++freq[c];
        priority_queue<pair<int, char>> available;
        for (const auto& p : freq) available.push({p.second, p.first});
        queue<pair<int, pair<int, char>>> cooldown;
        string result;
        for (int pos = 0; pos < (int)s.size(); ++pos)
        {
            while (!cooldown.empty() && cooldown.front().first <= pos)
            {
                available.push(cooldown.front().second);
                cooldown.pop();
            }
            if (available.empty()) return "";
            auto current = available.top();
            available.pop();
            result += current.second;
            if (--current.first > 0)
            {
                cooldown.push({pos + k, current});
            }
        }
        return result;
    }
};
